	INSERT INTO #supers(custid,Currency,site)
	SELECT ci.custid,ci.currency, cs.site
	FROM custInfo ci WITH (NOLOCK) 	
		INNER JOIN Dep_custsuper cs WITH (NOLOCK) ON ci.custid = cs.custid
	WHERE ci.username NOT LIKE '3rdSuper%'	
		AND ci.Enabled=1
		AND cs.site IN( '12Bet' , '365online' , '368Cash' , '3star88' , '9bet' , 'A1game' , 'Ae88' , 'AEUG' , 'ALPHA88' , 'Aoncash' , 'B24VN' , 'B8KRW' , 'bdtt' , 'beplay' , 'BigGaming' , 'Bolanation' , 'Bonanza88' , 'BPLE' , 'CGame4' , 'DEWA' , 'DMsports' , 'DongYing' , 'e8casino' , 'ECLBET' , 'erhaozhan' , 'FB88' , 'FHLMSABA' , 'GAMEBee' , 'Gampag' , 'Gaobet' , 'GBET' , 'GMASTER' , 'GoldenF2' , 'Hecbet' , 'HFTH' , 'iBET' , 'IBO' , 'ID88' , 'INSERTGAME' , 'ITCbet' , 'Jiuyou' , 'KzingP88' , 'LEIHUO' , 'Leng4D' , 'LIGAWLHKB' , 'Lode88' , 'M8bola' , 'Macaubet' , 'MANBETX' , 'Mancity2' , 'Mayayule' , 'Mopgaming' , 'MTech' , 'N8BK' , 'NewFuture' , 'OCMS' , 'Ot88' , 'Raisetech' , 'Rakyat4DSW' , 'SKY1688' , 'SM88' , 'Sunriseb2b' , 'Sunwin' , 'TCbet' , 'txwl002' , 'V03' , 'VFUN88' , 'VN88' , 'vssports' , 'W88' , 'WKPHIL' , 'wmcasino' , 'WRServices' , 'Xinbo' , 'Yibo' , 'YSYBO688' , 'ZF026' , 'ZF138THB' , 'ZF138USD' , 'ZF138VND' , 'ZF215aTR' , 'ZFRT126' , 'ZFRT132' , 'ZFRT144' , 'ZFRT151' , 'ZFRT166' , 'ZFRT179' , 'ZFRT186' , 'ZFRT195' , 'ZFRT213' , 'ZFRT218' , 'ZFRT276' , 'ZFRT282' , 'ZhiFeng009' , 'ZhiFeng012' , 'ZhiFeng021' , 'ZhiFeng032' , 'ZhiFeng035' , 'ZhiFeng036' , 'ZhiFeng040' , 'ZhiFeng041' , 'ZhiFeng147' , 'ZhiFeng176' , 'ZhiFeng222' , 'ZhiFeng228' , 'ZhiFeng229' , 'ZhiFeng258' , 'Zowin' , 'zt828')
		AND ci.currency IN (2,3,4,5,6,7,12,13,15,32,41,42,45,46,51,55,56,61,70,71,82,92,94,96,97,121,123) 				  
	ORDER BY ci.custid 
	
	CREATE TABLE #Dummy	(CustID INT PRIMARY KEY)
	INSERT INTO #Dummy(CustID)
	SELECT CustID FROM Customer WITH(NOLOCK) 
	WHERE srecommend IN(SELECT CustID FROM #supers) AND roleid=3 AND (username LIKE '%Acc%' OR username LIKE '%LocalBank%')
	-------------------------------------Betlimit Setting-----------------------------------------------
	CREATE TABLE #MemberTemp (CustID INT ,Sporttype INT, Bettype INT, MaxBet MONEY,MaxPerMatch MONEY,isfinished BIT DEFAULT(0),			PRIMARY KEY(CustID ,Sporttype, Bettype ))	
	CREATE TABLE #SMATemp  (CustID INT, Sporttype INT, Bettype INT, MaxBet MONEY,MaxPerMatch MONEY, 
		 PRIMARY KEY(CustID ,Sporttype, Bettype ))	
	--Agent Level
	INSERT INTO  #SMATemp (CustID, Sporttype, Bettype, MaxBet,MaxPerMatch)
	SELECT CI.custid, d.SportType, d.BetType, d.MaxBet, d.MaxPerMatch
	FROM Custinfo CI WITH (NOLOCK)
		INNER JOIN #supers C WITH (NOLOCK) ON C.custid = CI.srecommend
		INNER JOIN #data d WITH (NOLOCK) ON c.site = d.Site AND c.currency = d.currency
	WHERE ci.roleid IN (2,3,4) AND Enabled = 1 AND ci.custid > @maxcustid 
	AND ci.mrecommend NOT IN (SELECT custid FROM #Dummy)
	
	UPDATE dca 
	SET dca.MinBet= CASE WHEN dca.MinBet > c.MaxBet THEN c.MaxBet ELSE dca.MinBet END,
		dca.MaxBet=c.MaxBet, dca.MaxPerMatch=c.MaxPerMatch
	FROM Dep_CustBetSetting_Agent dca WITH (ROWLOCK, UPDLOCK)
		INNER JOIN #SMATemp c ON dca.CustID = c.CustID AND dca.SportType = c.SportType AND dca.BetType = c.BetType
	
	--Member Level
	INSERT INTO #MemberTemp  (CustID,Sporttype, Bettype, MaxBet,MaxPerMatch) 
	SELECT CI.custid, d.SportType, d.BetType, d.MaxBet, d.MaxPerMatch
	FROM Custinfo CI WITH (NOLOCK)
		INNER JOIN #supers C WITH (NOLOCK) ON C.custid = CI.srecommend
		INNER JOIN #data d WITH (NOLOCK) ON c.site = d.Site AND c.currency = d.currency
	WHERE  ci.roleid IN (1) AND Enabled = 1 AND ci.custid > @maxcustid AND CI.mrecommend NOT IN (SELECT custid FROM #Dummy)
	
	DECLARE @Cust_Temp TABLE(CustID INT, Sporttype INT, Bettype INT, MaxBet MONEY,MaxPerMatch MONEY)
	DECLARE @BatchSize SMALLINT = 5000
	
	WHILE(1 =1)
	BEGIN
		UPDATE TOP (@BatchSize) c WITH (ROWLOCK)
		SET c.isfinished = 1
		OUTPUT DELETED.CustID,DELETED.Sporttype,DELETED.Bettype,DELETED.MaxBet,DELETED.MaxPerMatch INTO @Cust_Temp(CustID,Sporttype,Bettype,MaxBet,MaxPerMatch)
		FROM #MemberTemp c 
		WHERE isfinished = 0
		
		IF @@ROWCOUNT = 0
		BEGIN 
			BREAK
		END 	
		
		UPDATE dca 
		SET dca.MinBet= CASE WHEN dca.MinBet > c.MaxBet THEN c.MaxBet ELSE dca.MinBet END,
			dca.MaxBet=c.MaxBet, dca.MaxPerMatch=c.MaxPerMatch
		FROM Dep_CustBetSetting_Member dca WITH (ROWLOCK, UPDLOCK)
			INNER JOIN @Cust_Temp c ON dca.CustID = c.CustID AND dca.SportType = c.SportType AND dca.BetType = c.BetType
		
		DELETE FROM @Cust_Temp
	END

	DROP TABLE #supers
	DROP TABLE #Dummy
	DROP TABLE #MemberTemp
	DROP TABLE #SMATemp
	PRINT N'Step 2: End on ' + CAST(GETDATE() AS NVARCHAR(30)) + N'.'; 

